package dev.sablelife.testing;
import dev.sablelife.module.*;
import dev.sablelife.attack.ModuleBlast;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
@GameTestHolder("sablelife_blast_tests") @PrefixGameTestTemplate(false)
public final class ImpactVisualGameTests {
 private static final class Author extends net.neoforged.neoforge.common.util.FakePlayer {private int next;Author(net.minecraft.server.level.ServerLevel level){super(level,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"ImpactAuthor"));setGameMode(net.minecraft.world.level.GameType.CREATIVE);}@Override public java.util.OptionalInt openMenu(net.minecraft.world.MenuProvider provider,java.util.function.Consumer<net.minecraft.network.RegistryFriendlyByteBuf> extra){closeContainer();containerMenu=provider.createMenu(++next,getInventory(),this);return java.util.OptionalInt.of(next);}}
 @GameTest(template="combat") public static void BothImpactParticleMenusEditTheParentAndRespectActiveLock(GameTestHelper h){
  var c=SlashGuardGameTests.core(h);var player=new Author(h.getLevel());player.setPos(ModuleArena.corePosition(c));var dashboard=new HeartDashboardMenu(1,player.getInventory(),c);
  for(String type:List.of("mortar","ground_strike")){var m=c.modules().add(type);h.assertTrue(dashboard.action(player,c.modules().revision(),m.id(),"effects","impactParticles",0,""),"Impact selector did not open: "+type);var menu=(EffectSelectionMenu)player.containerMenu;var child=m.movementParticles("Impact");h.assertTrue(menu.action(player,child.id(),"add",0,"minecraft:flame")&&child.particles().contains("minecraft:flame"),"Impact editor did not update parent");}
  c.tryActivate(player);var menu=(EffectSelectionMenu)player.containerMenu;var child=c.modules().all().getLast().movementParticles("Impact");h.assertTrue(!menu.action(player,child.id(),"remove",0,"minecraft:flame"),"Active life allowed impact editing");h.succeed();
 }
 @GameTest(template="combat") public static void IndependentVisualStyleSnapshotAndPresetKeepFlightSeparate(GameTestHelper h){
  for(String type:List.of("mortar","ground_strike")){
   var m=new VirtualModule(type);h.assertTrue(m.value("impactVisual")==0&&!SurfaceFieldSettings.visible(m,"impactParticles"),"Legacy default changed");m.edit("impactVisual",1,"");m.edit("impactSpreadMode",1,"");m.edit("impactSpreadRadius",12,"");m.edit("impactCount",1,"");var p=m.movementParticles("Impact");p.editParticle("remove","minecraft:explosion");p.editParticle("add","sablelife:light_ring");p.editParticle("size","sablelife:light_ring",4);p.editParticle("duration","sablelife:light_ring",2);p.editParticle("color","sablelife:light_ring",0x12AB34);
   var v=ImpactVisual.of(m,2);var roundtrip=ImpactVisual.load(v.save());h.assertTrue(v.equals(roundtrip)&&v.radius()==12&&v.position(Vec3.ZERO,0).equals(new Vec3(0,.2,0)),"Single particle was not centered or lost snapshot");h.assertTrue(v.particles().getFirst().size()==4&&v.particles().getFirst().ticks()==40,"Size/lifetime lost");
   var copy=ModulePreset.create(m.save());h.assertTrue(copy.movementParticles("Impact").particleEntries().equals(p.particleEntries())&&copy.value("impactSpreadRadius")==12,"Preset lost separate impact style");p.editParticle("remove","sablelife:light_ring");h.assertTrue(v.particles().size()==1&&ImpactVisual.of(m,2).particles().isEmpty(),"Snapshot followed edit or empty selection restored default");m.edit("impactSpreadMode",0,"");h.assertTrue(ImpactVisual.of(m,2).radius()==2&&!SurfaceFieldSettings.visible(m,"impactSpreadRadius"),"Follow mode does not use damage radius");
  }h.succeed();
 }
 @GameTest(template="combat") public static void BoundedDiskAndZeroRadiusDoNotChangeDamageRadius(GameTestHelper h){
  var m=new VirtualModule("mortar");m.edit("impactVisual",1,"");m.edit("blastRadius",2,"");m.edit("impactSpreadMode",1,"");m.edit("impactSpreadRadius",32,"");m.edit("impactCount",128,"");var v=ImpactVisual.of(m,2);for(int i=0;i<v.count();i++)h.assertTrue(v.position(Vec3.ZERO,i).multiply(1,0,1).length()<=32.000001,"Visual escaped radius");var tag=ModuleBlast.settings(m);m.edit("impactSpreadRadius",0,"");h.assertTrue(tag.getFloat("Radius")==2&&ImpactVisual.load(tag.getCompound("ImpactVisual")).radius()==32,"Visual changed damage or snapshot followed edits");for(int i=0;i<128;i++)h.assertTrue(ImpactVisual.of(m,2).position(Vec3.ZERO,i).equals(new Vec3(0,.2,0)),"Zero radius spread particles");h.succeed();
 }
 @GameTest(template="combat") public static void MortarCustomReplacesNativeExplosionAndKeepsDamage(GameTestHelper h){
  var l=h.getLevel();var point=h.absoluteVec(new Vec3(4,12,4));var player=TestActors.creative(l);player.setPos(point);var packets=new ArrayList<net.minecraft.network.protocol.Packet<?>>();player.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(l.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),player,net.minecraft.server.network.CommonListenerCookie.createInitial(player.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){packets.add(packet);}};l.players().add(player);
  var near=net.minecraft.world.entity.EntityType.COW.create(l);near.setNoAi(true);near.setNoGravity(true);near.setPos(point.add(1,0,0));l.addFreshEntity(near);var far=net.minecraft.world.entity.EntityType.COW.create(l);far.setNoAi(true);far.setNoGravity(true);far.setPos(point.add(5,0,0));l.addFreshEntity(far);
  try{var m=new VirtualModule("mortar");m.edit("blastRadius",2,"");m.edit("blastDamage",3,"");m.edit("impactVisual",1,"");m.edit("impactCount",1,"");m.edit("impactSpreadMode",1,"");m.edit("impactSpreadRadius",20,"");var p=m.movementParticles("Impact");p.editParticle("remove","minecraft:explosion");p.editParticle("add","sablelife:light_ring");p.editParticle("size","sablelife:light_ring",4);ModuleBlast.explode(l,null,point,ModuleBlast.settings(m));h.assertTrue(near.getHealth()==7&&far.getHealth()==10,"Visual spread changed blast damage radius");var visuals=packets.stream().filter(x->x instanceof net.minecraft.network.protocol.common.ClientboundCustomPayloadPacket c&&c.payload() instanceof ModuleNetworking.ParticleVisual).toList();h.assertTrue(visuals.size()==1&&packets.stream().noneMatch(x->x instanceof net.minecraft.network.protocol.game.ClientboundExplodePacket),"Custom effect retained native explosion or wrong count");var visual=(ModuleNetworking.ParticleVisual)((net.minecraft.network.protocol.common.ClientboundCustomPayloadPacket)visuals.getFirst()).payload();h.assertTrue(visual.id().equals("sablelife:light_ring")&&visual.size()==4,"Wrong impact size/type");packets.clear();m.edit("impactVisual",0,"");ModuleBlast.explode(l,null,point,ModuleBlast.settings(m));h.assertTrue(packets.stream().anyMatch(x->x instanceof net.minecraft.network.protocol.game.ClientboundExplodePacket),"Default native explosion no longer sent");h.succeed();}finally{l.players().remove(player);near.discard();far.discard();}
 }
}
